<script setup>
import { ref,watch } from 'vue';
import { libraryRequest } from '../lib/library-client.js';
const props=defineProps({bookId:{type:String,required:true},chapters:{type:Array,required:true}}),verificationMode=__VERIFICATION_MODE__;
const action=ref(verificationMode?'verification':'tts');
const policies=ref({force:false,resume:true,keep_imported:true,continue_on_error:true,cleanup:true,retries:2,verification_fail_chapters:[],verification_delay_ms:0,verification_fail_on_call:null,verification_fail_stage:'tts',verification_merge_failure:false});
const plan=ref(null),pending=ref(false),error=ref(''),requestId=ref(crypto.randomUUID());
watch(action,()=>{plan.value=null;requestId.value=crypto.randomUUID();});
watch(policies,()=>{plan.value=null;requestId.value=crypto.randomUUID();},{deep:true});
watch(()=>props.chapters.map(c=>c.id).join(','),()=>{plan.value=null;error.value='';requestId.value=crypto.randomUUID();});
async function preview(){pending.value=true;error.value='';try{plan.value=await libraryRequest('',{book_id:props.bookId,chapter_ids:props.chapters.map(c=>c.id),request_id:requestId.value,action:action.value,policies:policies.value},'POST','job-plans');requestId.value=crypto.randomUUID();}catch(e){error.value=e.message;}finally{pending.value=false;}}
async function confirm(){pending.value=true;error.value='';try{const result=await libraryRequest(`/${plan.value.id}/confirm`,{},'POST','job-plans');location.hash='jobs/'+result.id;}catch(e){error.value=e.message;}finally{pending.value=false;}}
</script>
<template>
  <div class="mt-5 rounded-lg border border-line bg-canvas p-4"><h4 class="text-sm font-semibold">Tạo tác vụ cho {{chapters.length}} chương đã chọn</h4><p class="mt-2 text-xs text-muted">Xem kế hoạch trước khi chạy. Mỗi lần kiểm thử tối đa20 chương.</p><label class="mt-3 grid gap-2 text-xs">Action<select id="plan-action" v-model="action" class="rounded border border-line bg-surface p-2" @change="plan=null"><option v-if="verificationMode" value="verification">Kiểm thử offline — provider giả lập</option><option value="tts">TTS các chương VI</option><option value="translate">Dịch sang tiếng Việt (toàn chương)</option><option value="process">Dịch sang tiếng Việt → TTS</option><option value="merge">Ghép audio chương đã có</option></select></label><div v-if="['tts','translate','process'].includes(action)" class="mt-4 grid gap-3 text-xs sm:grid-cols-2"><label><input id="policy-force" v-model="policies.force" type="checkbox" /> {{action==='translate'?'Xác nhận tạo bản dịch mới, giữ bản cũ':action==='process'?'Chạy lại cả dịch và TTS, giữ bản cũ':'Force — tạo lại audio/cache của phạm vi'}}</label><label v-if="['tts','process'].includes(action)"><input id="policy-resume" v-model="policies.resume" type="checkbox" :disabled="policies.force" /> Tái sử dụng cache phù hợp</label><label v-if="['tts','process'].includes(action)"><input id="policy-keep-imported" v-model="policies.keep_imported" type="checkbox" /> Giữ MP3 nhập trước, kể cả force</label><label><input id="policy-continue" v-model="policies.continue_on_error" type="checkbox" /> Tiếp tục chương sau khi có lỗi (bỏ tick để fail-fast)</label><label v-if="['tts','process'].includes(action)"><input id="policy-cleanup" v-model="policies.cleanup" type="checkbox" /> Dọn audio đoạn sau khi ghép thành công</label><label v-if="['tts','process'].includes(action)" class="flex items-center gap-2">Retry<input id="policy-retries" v-model.number="policies.retries" type="number" min="0" max="5" class="w-16 rounded border border-line bg-surface p-1" /></label><label v-if="verificationMode&&action==='process'" class="grid gap-2">Bước gây lỗi<select id="policy-fail-stage" v-model="policies.verification_fail_stage" class="rounded border border-line bg-surface p-2"><option value="tts">TTS</option><option value="translate">Dịch</option></select></label><label v-if="verificationMode" class="flex items-center gap-2">Độ trễ provider kiểm thử (ms)<input id="policy-delay" v-model.number="policies.verification_delay_ms" type="number" min="0" max="1000" class="w-20 rounded border border-line bg-surface p-1" /></label><label v-if="verificationMode" class="grid gap-2">Lỗi chủ động tại chương<select id="policy-fail-chapter" class="rounded border border-line bg-surface p-2" :value="policies.verification_fail_chapters[0]||''" @change="policies.verification_fail_chapters=$event.target.value?[$event.target.value]:[]"><option value="">Không gây lỗi</option><option v-for="chapter in chapters" :key="chapter.id" :value="chapter.id">{{chapter.number}} · {{chapter.title}}</option></select></label><label v-if="verificationMode&&policies.verification_fail_chapters.length" class="flex items-center gap-2">Gây lỗi ở lần gọi (trống = cả chương)<input id="policy-fail-call" type="number" min="1" max="100" :value="policies.verification_fail_on_call" class="w-20 rounded border border-line bg-surface p-1" @input="policies.verification_fail_on_call=$event.target.value?Number($event.target.value):null" /></label></div><div v-if="action==='merge'" class="mt-4 space-y-2 text-xs"><label class="block"><input id="merge-force" v-model="policies.force" type="checkbox" />Tạo bản ghép mới thay vì tái sử dụng bản cùng hash</label><label v-if="verificationMode" class="block"><input id="merge-inject-failure" v-model="policies.verification_merge_failure" type="checkbox" />Giả lập lỗi ghép để kiểm tra giữ bản cũ</label></div><button id="preview-job-plan" :disabled="pending||chapters.length>20" class="mt-3 rounded border border-line bg-surface px-3 py-2 text-xs disabled:opacity-50" @click="preview">Xem kế hoạch</button><p v-if="error" id="plan-error" role="alert" class="mt-3 text-xs">{{error}}</p>
    <div v-if="plan" id="job-plan" class="mt-4"><p class="text-xs leading-5 text-muted">{{plan.plan.notice}}</p><p v-if="plan.plan.action!=='merge'" class="mt-3 text-xs">Cấu hình snapshot: {{plan.plan.configuration.provider}} · {{plan.plan.configuration.voice||'giọng mặc định'}} · {{plan.plan.configuration.chunk_chars}} ký tự/đoạn · {{plan.plan.configuration.concurrency}} đồng thời</p><p v-if="plan.plan.merge" class="mt-2 text-xs">Tổng thời lượng đầu vào {{plan.plan.merge.input_duration.toFixed(2)}} giây · {{plan.plan.merge.reuse_artifact_id?'có bản ghép phù hợp để tái sử dụng':'tạo bản ghép riêng'}} · không gọi TTS.</p><p v-if="plan.plan.translation" class="mt-2 text-xs text-muted break-all">Model dịch {{plan.plan.translation.model}} · {{plan.plan.translation.glossary_entries.length}} thuật ngữ · Glossary {{plan.plan.translation.glossary_hash}} · Prompt {{plan.plan.translation.prompt_hash}}. Lỗi/stop dịch phải làm lại toàn chương chưa hoàn tất; TTS dùng checkpoint. Tổng đoạn TTS xác định sau khi có bản dịch.</p><p class="mt-2 text-xs font-medium">Thực thi: {{plan.plan.execution_provider}} · {{plan.plan.action==='merge'?'chỉ ghép file hiện có, không gọi TTS':verificationMode?'provider giả lập, không gọi giọng thật':'provider thật trong snapshot'}}.</p><ul class="mt-3 space-y-2 text-xs"><li v-for="chapter in plan.plan.chapters" :key="chapter.id">{{chapter.number??chapter.id}} · {{chapter.message}}</li></ul><button id="confirm-job-plan" :disabled="pending||plan.plan.chapters.some(c=>c.blocked)" class="mt-4 rounded-lg bg-brand px-4 py-2 text-xs text-brand-ink disabled:opacity-50" @click="confirm">Xác nhận chạy snapshot này</button></div>
  </div>
</template>
